#!/usr/bin/env python3
"""Self-contained licensed photo vs actual production-render comparison.
Run capture-car-comparison.mjs against the freshly rebuilt game first.
No network requests are needed to generate or view this HTML.
"""
import base64,hashlib,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];refs=json.loads((R/'data/car-references.json').read_text())['references'];roster=json.loads((R/'data/roster.json').read_text());teams=roster['eras'][4]['teams'];version=json.loads((R/'package.json').read_text())['version']
def esc(s):return html.escape(str(s),quote=True)
def image(path):return 'data:image/jpeg;base64,'+base64.b64encode(path.read_bytes()).decode()
notes={
'mercedes':('Black/turquoise body, silver rear star field, red INEOS band; #44.','The narrow nose is estimated. AMG stars, aerodynamic details and sponsor letterforms are simplified.'),
'red-bull':('Navy/red/yellow, Red Bull rather than the later giant ORACLE sidepod wordmark; #33.','The bull graphic is original stylized artwork. Small partner marks and exact bargeboard geometry are incomplete.'),
'ferrari':('Red with burgundy rear, Ray-Ban sidepod lettering, yellow accents; #16.','Logo shapes, race-specific sponsor placement and the actual SF21 nose/sidepods are approximations.'),
'aston-martin':('Green metallic finish, pink 2021 accent rather than later lime, Cognizant lettering; #5.','Exact BWT placements, metallic flake and AMR21 cooling details remain simplified.'),
'mclaren':('Papaya/blue 2021 scheme rather than 2023 exposed-carbon treatment, DARKTRACE; #3.','Colour boundaries, italic wordmarks and the individual MCL35M sidepod profile need further refinement.'),
'alpine':('Alpine blue with French red/white rear sweep and ALPINE lettering; #14.','The A-shaped graphics and individual A521 engine-cover/bulkhead details are approximated.'),
'williams':('White forward body with blue/cyan diagonal rear pattern; #63.','The dense FW43B pattern and sponsor set are simplified, not a traced corporate livery.'),
'alphatauri':('White/navy with stylized dark bull motif, ALPHATAURI and HONDA; #10.','The bull silhouette, negative-space graphics and small logos are not exact corporate vectors.'),
'alfa-romeo':('White forward body, dark red rear/sidepod panels, ORLEN and Alfa Romeo; #7.','The real C41 has specific crest/lettering and sidepod contours not fully reproduced here.'),
'haas':('White/red/blue VF-21 scheme and HAAS/URALKALI lettering; #47.','Flag-derived stripe curvature, italic HAAS logo and small sponsor positions remain approximate.')}
cards=[];capture_manifest=[]
for t in teams:
 id=t['id'];ref=next(r for r in refs if r['id']==id);capture=R/'artifacts/car-captures'/f'{id}.jpg'
 if not capture.exists():raise SystemExit('Missing actual game capture '+str(capture))
 shot=capture.read_bytes();capture_manifest.append(dict(id=id,sha256=hashlib.sha256(shot).hexdigest(),bytes=len(shot),source='Actual production showroom: same car meshes/materials used in races; standardized side camera, not AI imagery.'))
 good,limits=notes[id.removeprefix('2021-')]
 play='https://the-crab-post-office.github.io/apex-heritage/?season=2021&constructor='+id
 cards.append(f'''<article class="car" id="{id}" data-search="{esc(t['name'].lower()+' '+t['car'].lower())}" style="--team:{t['secondary']}">
 <header><div><span class="eyebrow">2021 · {esc(t['name'])}</span><h2>{esc(t['car'])} <small>#{t['number']}</small></h2></div><a class="drive" href="{esc(play)}" target="_blank" rel="noopener">Select in game ↗</a></header>
 <div class="pair"><figure><figcaption><b>01 / REFERENCE PHOTO</b><span>Austria 2021</span></figcaption><img src="{image(R/ref['file'])}" alt="Real {esc(t['name'])} {esc(t['car'])}, 2021 Austrian Grand Prix, by Lukas Raich" width="960" height="540" loading="lazy"><p class="credit">Photo © {esc(ref['author'])} · <a href="{esc(ref['source_page'])}" target="_blank" rel="noopener">Wikimedia Commons source</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Resized/recompressed.</p></figure>
 <figure><figcaption><b>02 / ACTUAL GAME RENDER</b><span>{version}</span></figcaption><img src="{image(capture)}" alt="Actual in-game {esc(t['name'])} {esc(t['car'])} showroom capture" width="1200" height="675" loading="lazy"><p class="credit">Production Three.js renderer · same meshes, livery atlas and team proportion variant as the race car. Not concept art.</p></figure></div>
 <div class="findings"><p><strong>WHAT CHANGED</strong>{esc(good)}</p><p><strong>STILL APPROXIMATE</strong>{esc(limits)}</p></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APEX / HERITAGE — 2021 car comparison</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#0d1117;color:#edf1f3}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-underline-offset:4px}main{max-width:1320px;margin:auto;padding:42px 30px 70px}.mast{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #2b3541;padding-bottom:20px;font-size:12px;letter-spacing:.16em}.pill{border:1px solid #344452;border-radius:100px;padding:9px 13px;color:#aee0cb}.hero{padding:50px 0 35px;max-width:970px}.eyebrow{font-size:11px;letter-spacing:.18em;color:#99a8b9;text-transform:uppercase}h1{font-size:clamp(42px,6vw,78px);letter-spacing:-.055em;line-height:1.04;margin:16px 0 25px;font-weight:700}h1 em{font-style:normal;color:#a5d5c4}.lead{font-size:17px;line-height:1.7;color:#bdc8d2;max-width:860px}.facts{display:flex;flex-wrap:wrap;gap:10px;margin:26px 0}.facts span{padding:10px 14px;background:#19222c;border:1px solid #2c3a47;border-radius:7px;font-size:12px}.note{border-left:3px solid #d2b978;padding:12px 18px;background:#1e1e1c;color:#d6cfbb;line-height:1.6;font-size:13px}.controls{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:34px 0 24px}.controls label{font-size:12px;color:#a9b6c3}input,select{font:inherit;background:#17212b;border:1px solid #354553;border-radius:7px;color:#f1f4f7;padding:11px 14px;min-width:225px}#count{margin-left:auto;font-size:12px;color:#9dafbe}.car{background:#141b23;border:1px solid #2d3945;border-top:3px solid var(--team);border-radius:12px;margin:0 0 28px;overflow:hidden}.car>header{padding:23px 26px;display:flex;justify-content:space-between;align-items:center;gap:12px}h2{margin:7px 0 0;font-size:29px;letter-spacing:-.03em}h2 small{font-size:17px;color:#a3b2c0;margin-left:12px}.drive{text-decoration:none;border:1px solid #405363;padding:10px 13px;border-radius:6px;font-size:12px;white-space:nowrap}.pair{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#35414e}figure{margin:0;background:#10161d;min-width:0}figcaption{padding:13px 18px;display:flex;justify-content:space-between;gap:8px;font-size:10px;letter-spacing:.1em}figcaption span{color:#9aabba;letter-spacing:0}img{display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:contain}.credit{font-size:10px;color:#a7b5c4;padding:0 18px;line-height:1.65;min-height:38px}.findings{padding:18px 26px 22px;display:grid;grid-template-columns:1fr 1fr;gap:28px}.findings p{font-size:12px;color:#bdc9d2;line-height:1.65;margin:0}.findings strong{display:block;letter-spacing:.13em;font-size:9px;color:#91cbb6;margin-bottom:7px}.findings p+ p strong{color:#c8b78f}.engineering{background:#17212b;border:1px solid #334352;padding:27px;border-radius:12px;line-height:1.75;font-size:13px;color:#bdc9d3}.engineering h2{color:#edf3f6;font-size:24px;margin-bottom:14px}.engineering ul{padding-left:20px}.engineering a{color:#c9e9df}footer{font-size:11px;color:#91a2b1;line-height:1.8;margin-top:32px}.hidden{display:none!important}@media(max-width:740px){main{padding:25px 16px}.hero{padding-top:32px}.pair,.findings{grid-template-columns:1fr}.findings{gap:16px}.car>header{padding:18px}.drive{font-size:10px}figcaption{padding:12px}.credit{min-height:0}input,select{min-width:0;width:100%}.controls label{width:100%}#count{margin:0}.mast{font-size:10px}.pill{letter-spacing:0}}
</style></head><body><main><div class="mast"><b>APEX / HERITAGE</b><span class="pill">VISUAL REFERENCE AUDIT · VERSION VERSION_TOKEN</span></div><section class="hero"><span class="eyebrow">The complete 2021 constructor grid</span><h1>Real cars.<br><em>Actual game renders.</em></h1><p class="lead">Ten licensed race photographs, ten captures of the cars you can drive. Compare body shape, tyre proportions, paint blocking and sponsor placement directly — including what still needs work.</p><div class="facts"><span>10 / 10 2021 teams</span><span>57 constructor-season entries</span><span>5 selectable eras</span><span>No photographic textures on cars</span></div><div class="note">These are original, photo-guided reconstructions, not scans or exact constructor CAD. Images use similar side views, but they are not camera-calibrated or pixel-aligned. No similarity score is claimed. Small logos, race-specific bodywork and sponsor lettering remain approximate.</div></section><div class="controls"><label>TEAM <select id="team"><option value="all">All ten teams</option>OPTIONS_TOKEN</select></label><label>FIND <input id="search" type="search" placeholder="Team or chassis…"></label><span id="count">10 comparisons</span></div><section id="cars">CARDS_TOKEN</section><section class="engineering"><span class="eyebrow">What is underneath</span><h2>A separate 2021 car, not a 2023 repaint.</h2><ul><li>Distinct flat stepped floor, diagonal floor edge, multi-vane bargeboards, narrower squared rear wing and open-spoke 13-inch rims. The 2023 cars retain their ground-effect floor treatment and larger 18-inch wheel covers. Modern tyre dimensions and wheel centres feed both the renderer and the four-patch contact model.</li><li>Team-specific nose/pod/engine-cover proportion adjustments are shared between browser and native clients. Paint finish distinguishes matte Red Bull/Ferrari from more reflective metallic liveries. Unmirrored alpha-backed sponsor decals follow the curved body rather than stretching one label over the whole car.</li><li>The 2021 handling preset uses a 752 kg base mass and eight forward ratios. Values beyond regulatory/reference dimensions remain gameplay estimates, not measured chassis telemetry.</li><li>Shared Rust handling now applies a combined-slip longitudinal/lateral tyre-force budget across all eras, sublinear tyre load sensitivity under downforce, braking/acceleration rear-load transfer and wheelbase-derived steering response. The existing deterministic collision and four-tyre contact solver remain; adding Rapier would not itself supply an F1 tyre model.</li></ul><p>Regulatory anchor: <a href="https://api.fia.com/sites/default/files/2021_formula_1_technical_regulations_-_iss_8_-_2021-02-19.pdf" target="_blank" rel="noopener">FIA 2021 Technical Regulations, issue 8, article 4.1</a>. This is not a full rigid-body suspension, thermal tyre, ERS or DRS simulation.</p><p><a href="https://the-crab-post-office.github.io/apex-heritage/" target="_blank" rel="noopener">Play the game ↗</a> &nbsp; · &nbsp; <a href="https://github.com/the-crab-post-office/apex-heritage" target="_blank" rel="noopener">Source and editable data ↗</a></p></section><footer><b>Photographic attribution.</b> All ten reference photographs: © Lukas Raich / Wikimedia Commons, 2021 Austrian Grand Prix, CC BY-SA 4.0. Individual file pages and license links appear with each image. The resized/JPEG-recompressed photographic adaptations remain CC BY-SA 4.0. Game captures are separate original rendered works. Brand names and simplified sponsor marks identify the represented cars; no endorsement or licensed corporate artwork is claimed. All images are embedded: this page works offline and does not contact an image CDN.</footer></main><script>const team=document.getElementById('team'),search=document.getElementById('search'),cars=[...document.querySelectorAll('.car')];function filter(){let n=0;for(const c of cars){const show=(team.value==='all'||c.id===team.value)&&c.dataset.search.includes(search.value.trim().toLowerCase());c.classList.toggle('hidden',!show);if(show)n++;}document.getElementById('count').textContent=n+' comparison'+(n===1?'':'s');}team.addEventListener('change',filter);search.addEventListener('input',filter);</script></body></html>'''
page=page.replace('VERSION_TOKEN',version).replace('OPTIONS_TOKEN',''.join(f'<option value="{t["id"]}">{esc(t["name"])} · {esc(t["car"])}</option>'for t in teams)).replace('CARDS_TOKEN',''.join(cards))
output=R/'web/public/car-comparison.html';output.parent.mkdir(exist_ok=True);output.write_text(page)
(R/'data/car-comparison-captures.json').write_text(json.dumps(dict(version=version,inputs={p:hashlib.sha256((R/p).read_bytes()).hexdigest() for p in ['data/car-shapes.json','data/car-variants.json','data/roster.json','web/assets/liveries/manifest.json']},camera='Standardized production showroom side view, 1200x675 JPEG. No camera-matching or photo registration.',captures=capture_manifest),indent=2)+'\n')
print('Wrote self-contained comparison:',output.stat().st_size,'bytes,',len(cards),'real-photo/game pairs')
